<span class="line"><span style="color:#ABB2BF;">    pred </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">bmm</span><span style="color:#ABB2BF;">(v, u.</span><span style="color:#61AFEF;">permute</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">))</span></span>
